import sys

def increment_base36(s):
    """Increment a base-36 string by one. Characters: 0-9 then A-Z."""
    chars = list(s)
    for i in range(len(chars) - 1, -1, -1):
        c = chars[i]
        if '0' <= c <= '8':
            chars[i] = chr(ord(c) + 1)
            return ''.join(chars)
        elif c == '9':
            chars[i] = 'A'
            return ''.join(chars)
        elif 'A' <= c <= 'Y':
            chars[i] = chr(ord(c) + 1)
            return ''.join(chars)
        elif c == 'Z':
            chars[i] = '0'
            # carry continues to next digit
        else:
            raise ValueError(f"Unexpected character: {c}")
    # If we fell through, we wrapped around entirely
    return '0' * len(chars)

def main():
    with open('ids.txt', 'r') as f:
        lines = [line.strip() for line in f if line.strip()]
    if not lines:
        # No ids yet, start from the beginning
        print("ORD-0000")
        return
    last_id = lines[-1]
    if not last_id.startswith("ORD-") or len(last_id) != 8:
        print(f"Error: invalid id format: {last_id}", file=sys.stderr)
        sys.exit(1)
    suffix = last_id[4:]
    next_suffix = increment_base36(suffix)
    print(f"ORD-{next_suffix}")

if __name__ == '__main__':
    main()
