#!/usr/bin/env python3
"""Read ids.txt and print the next order id."""

import re
from pathlib import Path

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def _base36_encode(n: int) -> str:
    """Encode an integer as uppercase base36."""
    if n == 0:
        return "0"
    chars = []
    while n > 0:
        chars.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(chars))


def next_id(ids_path: str = "ids.txt") -> str:
    """Return the next order id after the last one in ids.txt."""
    text = Path(ids_path).read_text().strip()
    if not text:
        raise ValueError("ids.txt is empty")

    last_line = text.splitlines()[-1].strip()
    m = re.fullmatch(r"ORD-([0-9A-Z]{4})", last_line)
    if not m:
        raise ValueError(f"Invalid last id: {last_line!r}")

    suffix = m.group(1)
    n = int(suffix, 36) + 1
    encoded = _base36_encode(n).rjust(4, "0")
    return f"ORD-{encoded}"


if __name__ == "__main__":
    print(next_id())

