#!/usr/bin/env python3
"""Read events.jsonl, remove duplicate events by event_id (keeping first occurrence),
and write deduplicated events to deduped.jsonl."""

import json

def dedupe():
    seen = set()
    deduped = []

    with open("events.jsonl", "r") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event["event_id"]
            if eid not in seen:
                seen.add(eid)
                deduped.append(event)

    with open("deduped.jsonl", "w") as f:
        for event in deduped:
            f.write(json.dumps(event) + "\n")

if __name__ == "__main__":
    dedupe()

