"""Print report file names under reports/ in report order."""

import os
import re

REPORTS_DIR = "reports"


def report_key(filename: str) -> int:
    """Extract the numeric suffix from a report filename for sorting."""
    match = re.search(r"(\d+)", filename)
    return int(match.group(1)) if match else 0


def main() -> None:
    try:
        files = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        print(f"error: '{REPORTS_DIR}/' not found", file=__import__("sys").stderr)
        raise SystemExit(1)

    # Filter to report-<n>.txt files and sort by numeric suffix
    reports = sorted(
        (f for f in files if re.match(r"^report-\d+\.txt$", f)),
        key=report_key,
    )

    for name in reports:
        print(name)


if __name__ == "__main__":
    main()

