import sys
from datetime import datetime, timezone


def parse_log_timestamp(line: str) -> datetime | None:
    """Extract the timestamp from the start of a log line (YYYY-MM-DD HH:MM:SS)."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except (ValueError, IndexError):
        return None


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("Error: AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - 7 * 24 * 60 * 60  # 7 days in seconds

    try:
        with open("app.log", "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: app.log not found", file=sys.stderr)
        sys.exit(1)

    kept = []
    archived = []

    for line in lines:
        dt = parse_log_timestamp(line)
        if dt is not None and dt.timestamp() < cutoff:
